import os, glob, re

def load_demos():
    """Load all demo pairs from current session"""
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    session_file = d + '/../../sessions/' + os.path.basename(d) + '.jsonl'

    if not os.path.exists(session_file):
        print(f"Session file not found: {session_file}")
        return {}

    with open(session_file, 'r') as f:
        content = f.read().replace('\\n', '\n')

    G = {}
    lines = content.split('\n')

    in_grid = False
    rows = []
    start_pos = 0
    current_k = None  # key like "Demo pair 4 input (17x10)"

    for i, line in enumerate(lines):
        # Look for grid headers
        grid_match = re.match(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):', line)
        if grid_match:
            # Save previous grid if we have one
            if in_grid and current_k is not None and rows:
                if current_k not in G:
                    keep = True
                    for r in rows:
                        if len(r) != int(lines[i-1].split()[-1].split('x')[1]):
                            keep = False
                            break
                    if keep:
                        new_grid = [[int(x) for x in r.split()] for r in rows]
                        G[current_k] = new_grid

            in_grid = True
            cols_str = line.split()[-1]
            _, rows, cols = cols_str.split()
            current_k = grid_match.group(1)
            rows = []
        elif in_grid and current_k is not None:
            # Parse grid row
            parts = line.split()
            if parts and parts[0].isdigit():
                rows.append(parts)
            else:
                # End of grid, save it
                if rows and current_k not in G:
                    w = len(rows[0])
                    grid = [[int(x) for x in row] for row in rows]
                    if all(len(r) == w for r in grid):
                        G[current_k] = grid
                in_grid = False
                rows = []

    # Save last grid
    if in_grid and current_k is not None and rows:
        w = len(rows[0])
        grid = [[int(x) for x in row] for row in rows]
        if all(len(r) == w for r in grid):
            G[current_k] = grid

    return G

G = load_demos()
print("Loaded grids:", sorted(G.keys()))
for k, grid in G.items():
    print(f"\n=== {k} ({len(grid)}x{len(grid[0]) if grid else 0}) ===")
    print(grid)

